function FloorPicker({ buildingId, selected, seats, policies, reservations, date, onChange }: {
  buildingId: BuildingId;
  selected: FloorId;
  seats: SeatRecord[];
  policies: SeatPolicyRecord[];
  reservations: SeatReservation[];
