  overflow: hidden;
  color: #4e5968;
  font-size: 13px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.upload-box small {
  margin-top: 3px;
  color: #a1a9b2;
  font-size: 10px;
}

.form-error {
