  background: transparent;
  color: var(--subtext);
  font-size: 13px;
  font-weight: 650;
}

.search-field {
  display: grid;
  height: 50px;
  grid-template-columns: 23px 1fr;
  align-items: center;
  gap: 7px;
  padding: 0 14px;
  border: 1px solid transparent;
