}

.search-field input {
  width: 100%;
  height: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  font-size: 13px;
}

.filter-tabs {
  display: flex;
  gap: 7px;
  margin: 17px -20px 0;
  padding: 0 20px 3px;
  overflow-x: auto;
  scrollbar-width: none;
}

.filter-tabs::-webkit-scrollbar {
