  border: 2px solid #d9dee4;
  border-radius: 50%;
  background: #fff;
  color: #fff;
}

.timeline-item.done .timeline-dot {
  border-color: var(--primary);
  background: var(--primary);
}

.timeline-line {
  position: absolute;
  top: 24px;
  bottom: 0;
  left: 11px;
