  padding-top: 1px;
}

.timeline-item b {
  color: #6b7684;
  font-size: 13px;
  font-weight: 650;
}

.timeline-item.done b {
  color: var(--text);
  font-weight: 720;
}

.timeline-item small {
  margin-top: 3px;
  color: #a1a9b2;
  font-size: 10px;
}

.detail-card dl {
  margin: 13px 0 0;
}

.detail-card dl > div {
  display: grid;
  grid-template-columns: 72px 1fr;
  gap: 10px;
  padding: 13px 0;
