}

.detail-description dd {
  margin-top: 8px;
  padding: 12px 13px;
  border-radius: 14px;
  background: #f6f7f8;
  color: #4e5968;
  font-weight: 500;
}

.secondary-button {
  margin-top: 18px;
  border: 1px solid #cfe2fd;
  background: var(--primary-soft);
  box-shadow: none;
  color: var(--primary);
}

.ops-intro {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 10px;
  padding: 9px 2px 19px;
}

.ops-intro h1 {
