  font-weight: 750;
}

.kpi-blue { background: #e8f2ff; color: #2478ed; }
.kpi-violet { background: #f0edff; color: #6655e9; }
.kpi-orange { background: #fff2df; color: #dc7b10; }
.kpi-green { background: #e7f8f1; color: #008d64; }

.sla-alert {
  margin-top: 13px;
  background: #fff1e9;
  color: #d86620;
}

.sla-alert > span:first-child {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 14px;
  background: #fff;
}

.sla-alert small {
  color: #a96d4b;
}

.ops-list-section {
  margin-top: 27px;
}

.ops-list-section > .section-heading {
  align-items: end;
  margin-bottom: 12px;
}

.ops-list-section .eyebrow {
  margin-bottom: 2px;
