  font-size: 9px;
  letter-spacing: 0.12em;
}

.ops-request-card {
  padding: 17px;
}

.priority {
  color: var(--muted);
  font-size: 11px;
  font-weight: 680;
}

.priority.urgent {
  display: inline-flex;
  padding: 5px 8px;
  border-radius: 9px;
  background: #fff0f2;
  color: var(--danger);
  font-size: 10px;
  font-weight: 780;
}

.ops-request-card h3 {
  margin: 13px 0 6px;
  font-size: 16px;
  font-weight: 760;
  letter-spacing: -0.03em;
}

.ops-request-card > p {
