  margin: 0;
  color: var(--subtext);
  font-size: 11px;
}

.ops-request-card > p svg {
  color: #a1a9b2;
}

.ops-owner {
  display: grid;
  grid-template-columns: 34px 1fr auto;
  align-items: center;
  gap: 9px;
  margin-top: 15px;
  padding: 12px;
  border-radius: 15px;
  background: #f6f7f8;
}

.owner-avatar {
  display: grid;
  width: 34px;
  height: 34px;
