  min-width: 0;
  flex-direction: column;
}

.ops-owner small {
  color: var(--muted);
  font-size: 9px;
}

.ops-owner b {
  overflow: hidden;
  margin-top: 1px;
  font-size: 11px;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-owner em {
  color: #7a8592;
  font-size: 10px;
  font-weight: 650;
}

.ops-owner em.sla-urgent {
  color: var(--danger);
}

.ops-action {
  min-height: 43px;
  margin-top: 12px;
  border-radius: 13px;
  box-shadow: none;
  font-size: 12px;
}

.toast {
  position: fixed;
  bottom: calc(91px + env(safe-area-inset-bottom));
  left: 50%;
  z-index: 50;
  display: flex;
  width: min(calc(100% - 40px), 440px);
  min-height: 49px;
  align-items: center;
  gap: 9px;
  padding: 11px 14px;
  border-radius: 16px;
  background: rgba(25, 31, 40, 0.94);
  box-shadow: 0 10px 28px rgba(25, 31, 40, 0.22);
  color: #fff;
  font-size: 12px;
  font-weight: 650;
  transform: translateX(-50%);
  animation: toast-in 180ms ease-out;
}

.toast > span {
  display: grid;
  width: 25px;
  height: 25px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 50%;
  background: #2fc98d;
}

@keyframes toast-in {
  from { opacity: 0; transform: translate(-50%, 8px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}

