.workflow-preview-head {
  display: flex;
  align-items: center;
  gap: 7px;
  color: #176fdc;
}

.workflow-preview-head > span {
  display: grid;
  width: 27px;
  height: 27px;
  place-items: center;
  border-radius: 10px;
  background: #fff;
}

.workflow-preview-head b {
  font-size: 12px;
  font-weight: 760;
}

.workflow-preview-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  margin-top: 12px;
}

.workflow-preview-grid > span {
  display: flex;
  min-width: 0;
  min-height: 58px;
  flex-direction: column;
  justify-content: center;
  padding: 8px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.82);
}

.workflow-preview-grid small {
  color: #7b91ab;
  font-size: 8px;
}

.workflow-preview-grid b {
  display: -webkit-box;
  margin-top: 2px;
  overflow: hidden;
  color: #385572;
  font-size: 9px;
  font-weight: 720;
  line-height: 1.35;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.workflow-preview > p {
  margin: 10px 1px 0;
  color: #627d99;
  font-size: 9px;
  line-height: 1.5;
}

.dynamic-fields {
  display: flex;
  flex-direction: column;
  gap: 22px;
}

.required-mark {
  display: inline-flex;
  margin-left: 6px;
  color: var(--primary);
  font-size: 9px;
  font-weight: 750;
  vertical-align: 1px;
}

.dynamic-field.has-error input,
.dynamic-field.has-error select,
.dynamic-field.has-error textarea,
.form-section.has-error input {
  border-color: #f48a95;
  box-shadow: 0 0 0 3px rgba(240, 68, 82, 0.08);
}

.form-section input[type="date"],
.form-section input[type="time"] {
  display: block;
  min-width: 0;
  max-width: 100%;
}

.field-inline-error {
  margin: -2px 2px 0;
  color: #d93a49;
  font-size: 10px;
  line-height: 1.45;
}

.other-input-block {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 12px;
  border: 1px solid #d9e9ff;
  border-radius: 15px;
  background: #f5f9ff;
}

.other-input-block > label {
  color: #385572;
  font-size: 12px;
  font-weight: 720;
}

.other-input-block textarea {
  min-height: 92px;
  border-color: #dbe8f7;
  background: #fff;
}

.check-field {
  display: grid;
  min-height: 62px;
  grid-template-columns: 24px 1fr;
  align-items: center;
  gap: 10px;
  padding: 11px 13px;
  border: 1px solid #e2e6ea;
  border-radius: 16px;
  background: #fff;
  cursor: pointer;
}

.check-field.checked {
  border-color: #91bcf8;
  background: #f4f8ff;
}

.check-field input {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
}

.check-control {
  display: grid;
  width: 23px;
  height: 23px;
  place-items: center;
  border: 1.5px solid #c8cfd7;
  border-radius: 8px;
  background: #fff;
  color: #fff;
}

.check-field.checked .check-control {
  border-color: var(--primary);
  background: var(--primary);
}

.check-field > span:last-child {
  display: flex;
  flex-direction: column;
}

.check-field b {
  font-size: 12px;
  font-weight: 690;
}

.check-field small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 9px;
}

.multi-choice-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
}

.multi-choice-grid button {
  display: flex;
  min-height: 43px;
  align-items: center;
  gap: 7px;
  padding: 8px 10px;
  border: 1px solid #e1e5e9;
  border-radius: 13px;
  background: #fff;
  color: #5d6876;
  font-size: 10px;
  font-weight: 650;
  text-align: left;
}

.multi-choice-grid button > span {
  display: grid;
  width: 17px;
  height: 17px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid #c9d0d7;
  border-radius: 6px;
  color: #fff;
}

.multi-choice-grid button.selected {
  border-color: #91bcf8;
  background: #f4f8ff;
  color: #2478ed;
}

.multi-choice-grid button.selected > span {
  border-color: var(--primary);
  background: var(--primary);
}

.auto-priority-card {
  display: grid;
  grid-template-columns: 38px 1fr;
  align-items: center;
  gap: 10px;
  min-height: 66px;
  padding: 12px;
  border: 1px solid #ffd0d5;
  border-radius: 16px;
  background: #fff3f4;
}

.auto-priority-card > span {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 13px;
  background: #fff;
  color: var(--danger);
}

.auto-priority-card > div {
  display: flex;
  flex-direction: column;
}

.auto-priority-card b {
  color: #d93b4a;
  font-size: 11px;
  font-weight: 730;
}

.auto-priority-card small {
  margin-top: 2px;
  color: #a96d73;
  font-size: 9px;
}

.review-summary-card {
  padding: 14px;
}

.review-priority {
  align-self: start;
  padding: 6px 9px;
  border-radius: 10px;
  background: #e8f2ff;
  color: var(--primary);
  font-size: 10px;
  font-weight: 740;
}

.review-priority.urgent {
  background: #fff0f2;
  color: var(--danger);
}

.detail-review-card > div {
  grid-template-columns: 92px 1fr;
}

.workflow-review-card {
  padding: 16px;
  border: 1px solid #d7e8ff;
  border-radius: 20px;
  background: #eff6ff;
}

.workflow-review-card h3 {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0 0 11px;
  color: #176fdc;
  font-size: 13px;
  font-weight: 750;
}

.workflow-review-card dl {
  margin: 0;
}

.workflow-review-card dl > div {
  display: grid;
  grid-template-columns: 68px 1fr;
  gap: 8px;
  padding: 8px 0;
  border-top: 1px solid rgba(130, 177, 236, 0.2);
}

.workflow-review-card dt {
  color: #7790aa;
  font-size: 10px;
}

.workflow-review-card dd {
  margin: 0;
  color: #395874;
  font-size: 10px;
  font-weight: 680;
}

.ops-service-item {
  display: inline-flex;
  width: fit-content;
  margin-top: -1px;
  padding: 4px 7px;
  border-radius: 8px;
  background: #f0f2f4;
  color: #6b7684;
  font-size: 9px;
  font-weight: 650;
}

.seat-home-shortcut {
  display: grid;
  width: 100%;
  min-height: 76px;
  grid-template-columns: 46px minmax(0, 1fr) 20px;
  align-items: center;
  gap: 11px;
  margin-top: 11px;
  padding: 12px 14px;
  border: 1px solid #dce8f8;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 5px 18px rgba(25, 31, 40, 0.04);
  text-align: left;
}

.seat-home-shortcut > span:nth-child(2) {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
}

.seat-home-shortcut b {
  font-size: 14px;
  font-weight: 760;
  letter-spacing: -0.025em;
}

.seat-home-shortcut small {
  color: var(--subtext);
  font-size: 10px;
}

.seat-home-shortcut > svg {
  color: #a3abb5;
}

.seat-home-icon,
.seat-admin-entry-icon {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 15px;
  background: #e7f7f1;
  color: #009b72;
}

.seat-admin-entry {
  display: grid;
  width: 100%;
  min-height: 102px;
  grid-template-columns: 50px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  margin-top: 13px;
  padding: 16px;
  border-radius: 23px;
  background: linear-gradient(135deg, #202b3a 0%, #263c51 100%);
  box-shadow: 0 10px 24px rgba(25, 40, 56, 0.16);
  color: #fff;
  text-align: left;
}

.ops-admin-tools {
  display: grid;
  gap: 10px;
  margin-top: 13px;
}

.ops-admin-tools .seat-admin-entry {
  margin-top: 0;
}

.budget-admin-entry {
  background: linear-gradient(135deg, #302a48 0%, #493d69 100%);
}

.budget-admin-entry .seat-admin-entry-icon {
  background: rgba(174, 151, 255, 0.17);
  color: #c8b9ff;
}

.budget-admin-entry small {
  color: #c8b9ff;
}

.seat-admin-entry > span:nth-child(2) {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.seat-admin-entry small {
  color: #82d9bd;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.11em;
}

.seat-admin-entry b {
  margin-top: 2px;
  font-size: 16px;
  font-weight: 770;
  letter-spacing: -0.03em;
}

.seat-admin-entry em {
  overflow: hidden;
  margin-top: 4px;
  color: rgba(255, 255, 255, 0.67);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.seat-admin-entry strong {
  display: flex;
  align-items: center;
  gap: 2px;
  color: rgba(255, 255, 255, 0.8);
  font-size: 10px;
  font-weight: 680;
  white-space: nowrap;
}

.seat-admin-entry .seat-admin-entry-icon {
  width: 48px;
  height: 48px;
  background: rgba(88, 212, 170, 0.15);
  color: #70d9b5;
}

.seat-screen {
  padding-top: 12px;
}

.seat-workday-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 16px;
  padding: 15px 2px 17px;
}

.seat-workday-hero .eyebrow {
  margin: 0 0 4px;
  color: #3182f6;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .12em;
}

.seat-workday-hero h1 {
  margin: 0;
  font-size: 27px;
  font-weight: 820;
  letter-spacing: -.045em;
}

.seat-workday-hero p:last-child {
  margin: 6px 0 0;
  color: #6b7684;
  font-size: 11px;
  line-height: 1.5;
}

.seat-workday-hero label {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.seat-workday-hero label span {
  color: #8b95a1;
  font-size: 8px;
  font-weight: 700;
}

.seat-workday-hero input {
  width: 132px;
  height: 42px;
  padding: 0 9px;
  border: 1px solid #dfe4e9;
  border-radius: 13px;
  background: #fff;
  color: #333d4b;
  font-size: 11px;
  font-weight: 650;
}

.seat-operation-summary {
  display: grid;
  min-height: 65px;
  grid-template-columns: 38px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  border: 1px solid #e1e8f2;
  border-radius: 18px;
  background: #f7faff;
}

.seat-operation-summary > span {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 13px;
  background: #e8f2ff;
  color: #3182f6;
}

.seat-operation-summary > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.seat-operation-summary small {
  color: #8b95a1;
  font-size: 8px;
}

.seat-operation-summary b {
  margin-top: 2px;
  overflow: hidden;
  color: #333d4b;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.seat-operation-summary em {
  padding: 6px 8px;
  border-radius: 9px;
  background: #e8f2ff;
  color: #2478ed;
  font-size: 8px;
  font-weight: 760;
  white-space: nowrap;
}

.seat-intro {
  padding: 10px 2px 20px;
}

.seat-intro .eyebrow,
.seat-admin-intro .eyebrow,
.seat-section-heading .eyebrow {
  margin-bottom: 3px;
  color: #3182f6;
  font-size: 9px;
  letter-spacing: 0.12em;
}

.seat-intro h1 {
  margin: 0;
  font-size: 27px;
  font-weight: 810;
  line-height: 1.28;
  letter-spacing: -0.045em;
}

.seat-intro > p:last-child,
.seat-admin-intro > div > p:last-child {
  margin: 9px 0 0;
  color: var(--subtext);
  font-size: 12px;
  line-height: 1.5;
}

.hybrid-seat-intro {
  padding-bottom: 15px;
}

.seat-policy-guide,
.seat-admin-floor-control {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  padding: 13px 14px;
  border: 1px solid #d9e6e1;
  border-radius: 18px;
  background: #f4fbf8;
}

.seat-policy-guide > div,
.seat-admin-floor-control > div {
  display: grid;
  min-width: 0;
  grid-template-columns: 39px minmax(0, 1fr);
  align-items: center;
  gap: 9px;
}

.policy-guide-icon,
.seat-admin-floor-control > div > span:first-child {
  display: grid;
  width: 39px;
  height: 39px;
  place-items: center;
  border-radius: 13px;
  background: #dcf5eb;
  color: #008b66;
}

.seat-policy-guide > div > span:last-child,
.seat-admin-floor-control > div > span:last-child,
.seat-policy-guide label {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.seat-policy-guide small,
.seat-admin-floor-control small,
.seat-policy-guide label span {
  color: #6b7684;
  font-size: 8px;
}

.seat-policy-guide b,
.seat-admin-floor-control b {
  overflow: hidden;
  margin-top: 2px;
  font-size: 10px;
  font-weight: 760;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.seat-policy-guide input,
.seat-admin-floor-control input {
  width: 124px;
  height: 38px;
  margin-top: 4px;
  padding: 0 7px;
  border: 1px solid #cddfd8;
  border-radius: 11px;
  background: #fff;
  font-size: 10px;
}

.my-space-cards {
  display: flex;
  flex-direction: column;
  gap: 9px;
  margin-top: 12px;
}

.my-seat-card {
  display: grid;
  width: 100%;
  min-height: 88px;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  padding: 14px;
  border: 1px solid #dce8f8;
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 5px 16px rgba(25, 31, 40, 0.04);
  color: #333d4b;
  text-align: left;
}

.shared-reservation-card {
  border-color: #cfeae1;
  background: #fbfefd;
}

.my-seat-card > span:first-child {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 14px;
  background: #e8f2ff;
  color: #3182f6;
}

.shared-reservation-card > span:first-child { background: #e5f7f0; color: #009b72; }

.my-seat-card > div {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.my-seat-card small {
  color: #8b95a1;
  font-size: 9px;
}

.my-seat-card b {
  margin-top: 1px;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.my-seat-card em {
  overflow: hidden;
  margin-top: 3px;
  color: #6b7684;
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.my-seat-card strong {
  color: #3182f6;
  font-size: 9px;
  font-weight: 680;
  white-space: nowrap;
}

.seat-section-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  margin-top: 28px;
}

.seat-section-heading h2 {
  margin: 0;
  font-size: 20px;
  font-weight: 790;
  letter-spacing: -0.035em;
}

.seat-section-heading > span {
  color: var(--subtext);
  font-size: 10px;
}

.seat-section-heading > span b {
  margin-right: 2px;
  color: #009b72;
  font-size: 16px;
}

.floor-picker-wrap {
  margin-top: 13px;
}

.floor-picker-label {
  display: block;
  margin: 0 0 7px 2px;
  color: #8b95a1;
  font-size: 9px;
  font-weight: 700;
}

.floor-picker {
  display: flex;
  gap: 7px;
  margin: 0 -20px;
  padding: 0 20px 2px;
  overflow-x: auto;
  scrollbar-width: none;
}

.floor-picker::-webkit-scrollbar { display: none; }

.floor-picker button {
  display: flex;
  min-width: 94px;
  height: 52px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  border: 1px solid #e2e6ea;
  border-radius: 15px;
  background: #fff;
  color: #4e5968;
}

.floor-picker button.selected {
  border-color: #333d4b;
  background: #333d4b;
  box-shadow: none;
  color: #fff;
}

.floor-picker b {
  font-size: 13px;
  font-weight: 780;
}

.floor-picker small {
  color: var(--muted);
  font-size: 8px;
}

.floor-picker button.selected small {
  color: rgba(255, 255, 255, .68);
}

.seat-tools {
  margin-top: 14px;
}

.seat-search {
  display: grid;
  height: 48px;
  grid-template-columns: 21px minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  padding: 0 13px;
  border: 1px solid #dfe4e9;
  border-radius: 15px;
  background: #fff;
  color: var(--muted);
}

.seat-search:focus-within {
  border-color: #72aaf4;
  box-shadow: 0 0 0 3px rgba(49, 130, 246, 0.1);
  color: var(--primary);
}

.seat-search input {
  min-width: 0;
  height: 100%;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
  font-size: 13px;
}

.seat-quick-filters {
  display: flex;
  gap: 7px;
  margin-top: 9px;
  overflow-x: auto;
  scrollbar-width: none;
}

.seat-quick-filters::-webkit-scrollbar {
  display: none;
}

.seat-quick-filters button {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  gap: 5px;
  padding: 7px 12px;
  border: 1px solid #e1e5e9;
  border-radius: 999px;
  background: #fff;
  color: #6b7684;
  font-size: 9px;
  font-weight: 680;
  white-space: nowrap;
}

.seat-quick-filters button.selected {
  border-color: #333d4b;
  background: #333d4b;
  color: #fff;
}

.seat-quick-filters svg {
  width: 14px;
  height: 14px;
}

.seat-quick-filters .filter-reset {
  border-color: transparent;
  background: #f2f4f6;
  color: #4e5968;
}

.seat-legend {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 14px 1px 8px;
  overflow-x: auto;
  color: var(--subtext);
  font-size: 8px;
  scrollbar-width: none;
}

.seat-legend::-webkit-scrollbar {
  display: none;
}

.seat-legend span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

.seat-legend i {
  width: 9px;
  height: 9px;
  border: 1px solid transparent;
  border-radius: 3px;
}

.legend-available { border-color: #51c79f !important; background: #e2f7f0; }
.legend-assigned { border-color: #c2cad2 !important; background: #e7ebef; }
.legend-pending { border-color: #eebd55 !important; background: #fff0c9; }
.legend-reserved { border-color: #7e9bf0 !important; background: #e5ecff; }
.legend-dual { border: 0 !important; border-radius: 50% !important; background: #7b61e8; }
.legend-fixed { border-color: #6f8cac !important; background: #edf2f7; }
.legend-shared { border-color: #00a477 !important; background: repeating-linear-gradient(135deg, #dcf6ed 0 3px, #fff 3px 5px); }
.legend-selected { border-color: #3182f6 !important; background: #3182f6; box-shadow: 0 0 0 2px #dbeaff; }

.seat-map-section {
  overflow: hidden;
  border: 1px solid #dde2e7;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 6px 18px rgba(25, 31, 40, 0.04);
}

.seat-map-toolbar {
  display: flex;
  min-height: 61px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px 10px 15px;
  border-bottom: 1px solid #edf0f2;
}

.seat-map-toolbar > div:first-child {
  display: flex;
  min-width: 0;
  flex-direction: column;
}

.seat-map-kicker {
  margin-bottom: 1px;
  color: #3182f6;
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.seat-map-toolbar b {
  font-size: 13px;
  font-weight: 760;
}

.seat-map-toolbar small {
  overflow: hidden;
  margin-top: 2px;
  color: var(--muted);
  font-size: 8px;
  text-overflow: ellipsis;
