export const INTEGRATION_SCHEMA_VERSION = "1.0.0" as const;

export type IntegrationTarget = "ITSM" | "POP" | "SAP" | "AMS" | "SLACK";
export type IntegrationSyncStatus = "not_connected" | "pending" | "synced" | "failed";

export type IntegrationField = {
  key: string;
  label: string;
  value: string;
};

export type ExternalReference = {
  system: IntegrationTarget;
  externalId: string;
  status: string;
  lastSyncedAt?: string;
};

export type IntegrationEnvelope = {
  schemaVersion: typeof INTEGRATION_SCHEMA_VERSION;
  source: "workplace-portal";
  requestId: string;
  idempotencyKey: string;
  correlationId: string;
  createdAt: string;
  channel: "web" | "slack" | "teams" | "email";
  actor: {
    type: "employee" | "contractor";
    subjectId?: string;
    departmentCode?: string;
  };
  catalog: {
    categoryCode: string;
    itemCode: string;
  };
  request: {
    title: string;
    priority: "일반" | "긴급";
    location: string;
    description: string;
    fields: IntegrationField[];
  };
  workflow: {
    status: "접수" | "처리 중" | "완료";
    route?: string;
    approval?: string;
    sla: string;
  };
  sync: {
    status: IntegrationSyncStatus;
    externalReferences: ExternalReference[];
  };
};

type CreateIntegrationEnvelopeInput = {
  requestId: string;
  categoryCode: string;
  itemCode: string;
  title: string;
  priority: "일반" | "긴급";
  location: string;
  description: string;
  fields?: Array<{ key?: string; label: string; value: string }>;
  route?: string;
  approval?: string;
  sla: string;
  actor?: IntegrationEnvelope["actor"];
  channel?: IntegrationEnvelope["channel"];
  createdAt?: string;
};

export function createIntegrationEnvelope(input: CreateIntegrationEnvelopeInput): IntegrationEnvelope {
  return {
    schemaVersion: INTEGRATION_SCHEMA_VERSION,
    source: "workplace-portal",
    requestId: input.requestId,
    idempotencyKey: `workplace:${input.requestId}`,
    correlationId: input.requestId,
    createdAt: input.createdAt ?? new Date().toISOString(),
    channel: input.channel ?? "web",
    actor: input.actor ?? { type: "employee" },
    catalog: {
      categoryCode: input.categoryCode,
      itemCode: input.itemCode,
    },
    request: {
      title: input.title,
      priority: input.priority,
      location: input.location,
      description: input.description,
      fields: (input.fields ?? []).map((field) => ({
        key: field.key ?? field.label,
        label: field.label,
        value: field.value,
      })),
    },
    workflow: {
      status: "접수",
      route: input.route,
      approval: input.approval,
      sla: input.sla,
    },
    sync: {
      status: "not_connected",
      externalReferences: [],
    },
  };
}

import assert from "node:assert/strict";
import test from "node:test";

const developmentPreviewMeta =
  /<meta(?=[^>]*\bname=["']codex-preview["'])(?=[^>]*\bcontent=["']development["'])[^>]*>/i;

test("renders development preview metadata", async () => {
  const workerUrl = new URL("../dist/server/index.js", import.meta.url);
  workerUrl.searchParams.set("test", `${process.pid}-${Date.now()}`);
  const { default: worker } = await import(workerUrl.href);

  const response = await worker.fetch(
    new Request("http://localhost/", {
      headers: { accept: "text/html" },
    }),
    {
      ASSETS: {
        fetch: async () => new Response("Not found", { status: 404 }),
      },
    },
    {
      waitUntil() {},
      passThroughOnException() {},
    },
  );

  assert.equal(response.status, 200);
  assert.match(
    response.headers.get("content-type") ?? "",
    /^text\/html\b/i,
  );
  assert.match(await response.text(), developmentPreviewMeta);
});

#!/usr/bin/env bash
set -euo pipefail

script_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

if [[ "${SITES_ENV_READY:-}" != "1" ]]; then
  exec "${script_dir}/sites-env.sh" -- "$0" "$@"
fi

worker="${SITES_PROJECT_ROOT}/dist/server/index.js"
hosting="${SITES_PROJECT_ROOT}/dist/.openai/hosting.json"

[[ -f "${worker}" ]] || {
  echo "Missing Sites Worker entry: dist/server/index.js" >&2
  exit 66
}
[[ -f "${hosting}" ]] || {
  echo "Missing packaged Sites manifest: dist/.openai/hosting.json" >&2
  exit 66
}

node --input-type=module - "${worker}" "${hosting}" <<'NODE'
import { readFile } from "node:fs/promises";
import { pathToFileURL } from "node:url";

const [workerPath, hostingPath] = process.argv.slice(2);
JSON.parse(await readFile(hostingPath, "utf8"));

const workerUrl = pathToFileURL(workerPath);
workerUrl.searchParams.set("sites-validation", `${process.pid}-${Date.now()}`);
const worker = await import(workerUrl.href);
if (!worker.default || typeof worker.default.fetch !== "function") {
  throw new Error("dist/server/index.js must have an ESM default export with fetch(request, env, ctx)");
}
NODE

echo "Validated Sites artifact: ESM Worker default.fetch and hosting manifest are present."
